const debounce = (fn, timeout) => {
    let timerId;

    return function(...args) {
        clearTimeout(timerId);
        timerId = setTimeout(() => {
            fn.apply(this, args);
        }, timeout);
    }
}

const throttle = (fn, time) => {
  	// 上一次函数执行的时间
    let pre = 0;

    return function(...args) {
        let now = Date.now();
        if (now - pre > time) {
            fn.apply(this, args);
            pre = now;
        }
    }
}
